from lib import *
chapter(6,'science','exploring-magnets','Exploring Magnets',
 ('The fridge door','A small magnet sticks to a fridge door, but not to a wooden table. Why? Magnets seem magical, but they follow clear rules that we can test.'),
 [('Magnetic and non-magnetic materials',['A magnet attracts some materials, such as iron, nickel and cobalt. These are magnetic materials.','Materials like wood, plastic, glass, paper and rubber are not attracted. They are non-magnetic.','Test by bringing a magnet near an object and seeing if it sticks.']),
  ('Poles of a magnet',['Every magnet has two ends called poles where the pull is strongest: the north pole and the south pole.','If we break a magnet, each piece still has two poles.','A freely hanging bar magnet comes to rest pointing north and south.']),
  ('Attraction and repulsion',['Unlike poles attract each other. A north pole pulls a south pole.','Like poles repel each other. Two north poles push apart.','Repulsion is the only sure test to tell if something is a magnet, since a magnet attracts iron too.']),
  ('Finding directions',['A magnetic compass has a small magnetised needle that points north and south.','We use a compass to find directions when we are lost or at sea.']),
  ('Using magnets',['Magnets are used in fridge doors, speakers, toys, cranes and in separating iron from waste.','Keep magnets away from phones, cards and computers because they can be damaged.'])],
 [('How can you find which end of an unmarked bar magnet is north?',[('Hang it from a thread so it turns freely.','Reduce friction.'),('The end that points north is the north pole.','The Earth acts like a giant magnet.')])],
 ('A friend says a magnet attracts everything. How would you show it does not?',['Test wood, plastic and iron.','Only iron, nickel and cobalt stick.'],['Thinking steel and all metals are magnetic.','Thinking only one pole attracts.']),
 ['Magnets attract iron, nickel and cobalt.','Every magnet has two poles.','Like poles repel and unlike attract.','A compass points north-south.'],
 [mcq('g4-1',1,'Which is magnetic?','An iron nail',[('A plastic comb','Plastic is non-magnetic.'),('A wooden spoon','Wood is non-magnetic.')],'Iron is attracted by magnets.'),
  mcq('g4-2',1,'Like poles of two magnets','repel',[('attract','Unlike poles attract.'),('do nothing','They push apart.')],'North repels north.'),
  tf('g4-3',1,'Every magnet has two poles.',True,'Even a small piece has both poles.'),
  mcq('g4-4',1,'A compass needle points','north-south',[('east-west','It aligns with the Earth\'s poles.'),('up-down','It lies flat on the dial.')],'Earth acts like a magnet.'),
  mcq('g4-5',2,'The sure test for a magnet is','repulsion',[('attraction','Iron is attracted by a magnet.'),('colour','Colour tells nothing.')],'Only a magnet repels another magnet.'),
  mcq('g4-6',2,'If a bar magnet breaks into two','each piece is a magnet with two poles',[('one piece loses magnetism','Both are magnets.'),('there is only one pole','Poles always come in pairs.')],'Poles cannot be separated.'),
  tf('g4-7',2,'Glass is attracted by a magnet.',False,'Glass is non-magnetic.'),
  mcq('g4-8',2,'Magnets should be kept away from','mobile phones',[('wooden tables','Wood is not affected.'),('plants','Plants are not affected.')],'They can damage electronics and cards.'),
  mcq('g4-9',3,'A magnet is hung freely and its north-pointing end is','its north pole',[('its south pole','The north-seeking end is the north pole.'),('no pole','Poles are at the ends.')],'Named for pointing north.'),
  mcq('g4-10',3,'To separate iron nails from sand use','a magnet',[('a sieve only','Nails and sand may pass.'),('water only','Both sink.')],'The magnet picks up iron.')],
 keep=['magnet','pole','compass'])
chapter(6,'science','measurement-of-length-and-motion','Measurement of Length and Motion',
 ('How long is the desk?','Ravi measures the desk with his hand span and gets 7. Meena gets 6. Same desk, different answers! To avoid this we need standard units.'),
 [('Why measure?',['Measurement gives numbers so everyone can agree. Long ago people used a hand span or a foot, but those differ from person to person.','So we use standard units, the same for everyone.']),
  ('Standard units',['The standard unit of length in the SI system is the metre. Smaller lengths use the centimetre and millimetre. Long distances use the kilometre.','1 metre equals 100 centimetres. 1 centimetre equals 10 millimetres. 1 kilometre equals 1000 metres.']),
  ('Correct way to measure length',['Place the ruler along the object with zero at one end. Look straight down at the mark to avoid parallax error.','If the end of the ruler is worn, start from a clear mark like 1 cm and subtract.','To measure a curved line, lay a thread along it, straighten the thread and measure the thread.']),
  ('Position and motion',['An object is in motion when its position changes with time compared with a fixed point, called a reference point.','A person sitting in a moving bus is at rest for the seat but moving for the road.']),
  ('Types of motion',['Straight line motion is movement along a line, such as a car on a straight road.','Circular motion is movement around a fixed point, such as a point on a fan blade.','Periodic motion repeats at regular intervals, like a swing or a pendulum.','Rotational motion is spinning about an axis, like a top.'])],
 [('Convert 3 metres to centimetres.',[('1 metre is 100 centimetres.','Know the relation.'),('3 times 100 is 300 centimetres.','Multiply.')])],
 ('Explain why we need standard units.',['Body parts differ, so measures differ.','Standard units give the same answer for everyone.'],['Reading the ruler from the side.','Starting at the wrong mark.']),
 ['The SI unit of length is the metre.','1 m = 100 cm, 1 cm = 10 mm, 1 km = 1000 m.','Measure with zero at the start and look straight down.','Motion is change of position compared to a reference point.','Motion types: straight, circular, periodic, rotational.'],
 [mcq('m5-1',1,'The SI unit of length is the','metre',[('centimetre','This is a smaller unit.'),('kilometre','This is a larger unit.')],'SI stands for international units.'),
  num('m5-2',1,'How many centimetres in 2 metres?',200,'2 times 100.',[(20,'1 m is 100 cm.')],'cm'),
  tf('m5-3',1,'A hand span is a standard unit.',False,'It varies between people.'),
  mcq('m5-4',1,'A swing moves with','periodic motion',[('straight motion','A swing goes back and forth in a curve.'),('no motion','It repeats regularly.')],'It repeats at regular intervals.'),
  mcq('m5-5',2,'To measure a curved line use','a thread',[('a rigid ruler only','It cannot follow the curve.'),('your eyes','This is inaccurate.')],'Straighten the thread and measure it.'),
  num('m5-6',2,'How many metres in 3 km?',3000,'1 km equals 1000 m.',[(300,'1 km is 1000 m not 100.')],'m'),
  mcq('m5-7',2,'Object at rest compared to its reference means','position does not change',[('it is moving fast','Rest means no change.'),('it has no weight','Weight is unrelated.')],'Rest and motion depend on the reference.'),
  mcq('m5-8',2,'A fan blade point moves in','circular motion',[('straight line','It moves around the centre.'),('random motion','It follows a circle.')],'Around a fixed point.'),
  tf('m5-9',3,'A passenger in a moving train is at rest relative to the train.',True,'The position relative to the train does not change.'),
  mcq('m5-10',3,'Parallax error comes from','looking at the scale from an angle',[('a long ruler','Length does not matter.'),('cold weather','Temperature is unrelated.')],'Look straight down at the mark.')],
 keep=['metre','motion','reference point'])
chapter(6,'science','materials-around-us','Materials Around Us',
 ('The school bag','Look at your school bag. The bag is cloth, the zip is metal, the bottle is plastic and the pencil is wood. Why are different materials used for different things?'),
 [('Objects and materials',['Everything around us is made of materials. An object can be made of one or many materials.','Materials may come from nature, like wood and cotton, or be made by people, like plastic.']),
  ('Grouping materials',['We group materials by their properties, such as hardness, shine, transparency, and whether they float or dissolve in water.','Rough or smooth, hard or soft, light or heavy are also properties.']),
  ('Properties',['Metals are usually hard and shiny, and they conduct heat and electricity.','Transparent materials like clear glass let light pass through completely. Translucent materials let some light through. Opaque materials, like wood and metal, let none through.','Some solids dissolve in water, like salt and sugar, and some do not, like sand and chalk.','Some materials float on water and some sink, depending on how heavy they are for their size.']),
  ('Matter',['Anything that has mass and takes up space is matter.','Air is matter, even though we cannot see it, because it fills space and has weight.','Matter exists as solids, liquids and gases.']),
  ('Choosing materials',['We choose a material because its properties suit the use. Cooking pans are metal because metal conducts heat. Handles are plastic or wood because they do not conduct heat well.'])],
 [('Why are windows made of glass?',[('Glass is transparent.','Light can enter.'),('So we can see through and let light in.','Property matches use.')])],
 ('Explain why a pan has a plastic handle.',['The pan metal conducts heat.','The handle must not.'],['Thinking all shiny things are metal.','Thinking air is nothing.']),
 ['Materials are grouped by properties.','Transparent, translucent and opaque describe light passing.','Matter has mass and takes up space.','The choice of material depends on its use.'],
 [mcq('t6-1',1,'A material that lets all light pass is','transparent',[('opaque','Opaque blocks light.'),('translucent','Translucent lets some light through.')],'Clear glass is transparent.'),
  mcq('t6-2',1,'Which dissolves in water?','Salt',[('Sand','Sand stays as grains.'),('Chalk','Chalk is insoluble.')],'Salt disappears into water.'),
  tf('t6-3',1,'Air is matter.',True,'It has mass and takes up space.'),
  mcq('t6-4',1,'An opaque material is','wood',[('clear glass','Glass is transparent.'),('air','Air is transparent.')],'Wood blocks light.'),
  mcq('t6-5',2,'Cooking pans are metal because metals','conduct heat',[('are soft','Metals are generally hard.'),('are light','Pans can be heavy.')],'Heat passes through quickly.'),
  mcq('t6-6',2,'Frosted glass is','translucent',[('opaque','Opaque lets no light through.'),('transparent','Transparent is fully clear.')],'It lets some light through.'),
  tf('t6-7',2,'All solids sink in water.',False,'A wooden block floats.'),
  mcq('t6-8',2,'Matter exists as','solid, liquid and gas',[('only solid','Water and air are matter too.'),('only gas','Many things are solid.')],'Three states.'),
  mcq('t6-9',3,'A rubber eraser is used on pencils because it is','soft and rubs off graphite',[('transparent','That does not help.'),('magnetic','Irrelevant.')],'Its property suits the use.'),
  mcq('t6-10',3,'To test if material floats you','put it in water',[('weigh it only','Weight alone does not decide.'),('heat it','Heat is another test.')],'Observe whether it floats.')],
 keep=['transparent','opaque','matter'])
